    fun getIconResource(merchantName: String): Int? {
        val normalized = merchantName.lowercase()

        if (normalized.contains("cred") && !normalized.contains("credit")) {
            brandMappings["cred"]?.let { return it }
        }

        return brandMappings.entries
            .sortedByDescending { it.key.length }
            .firstOrNull { (key, _) ->
                key != "cred" && normalized.contains(key)
            }
            ?.value
    }
    
    fun getBrandColor(merchantName: String): String? = when {
        // Entertainment
        merchantName.contains("netflix", ignoreCase = true) -> "#E50914"
        merchantName.contains("spotify", ignoreCase = true) -> "#1DB954"
        merchantName.contains("youtube", ignoreCase = true) -> "#FF0000"
        merchantName.contains("disney", ignoreCase = true) -> "#113CCF"
        merchantName.contains("sony", ignoreCase = true) -> "#000000"
        merchantName.contains("zee", ignoreCase = true) -> "#6C2E91"
        merchantName.contains("voot", ignoreCase = true) -> "#E5007E"
        
        // Food
        merchantName.contains("swiggy", ignoreCase = true) -> "#FC8019"
        merchantName.contains("zomato", ignoreCase = true) -> "#E23744"
        merchantName.contains("blinkit", ignoreCase = true) -> "#FFC800"
        merchantName.contains("zepto", ignoreCase = true) -> "#9B51E0"
        merchantName.contains("dominos", ignoreCase = true) -> "#0066B3"
        merchantName.contains("mcdonalds", ignoreCase = true) -> "#FFC600"
        merchantName.contains("kfc", ignoreCase = true) -> "#F40027"
        merchantName.contains("starbucks", ignoreCase = true) -> "#00704A"
        
        // Banks
        merchantName.contains("hdfc", ignoreCase = true) -> "#004C8F"
        merchantName.contains("icici", ignoreCase = true) -> "#F37021"
        merchantName.contains("axis", ignoreCase = true) -> "#97144D"
        merchantName.contains("sbi", ignoreCase = true) || 
        merchantName.contains("state bank of india", ignoreCase = true) -> "#22409A"
        merchantName.contains("kotak", ignoreCase = true) -> "#EF3829"
        merchantName.contains("yes bank", ignoreCase = true) -> "#0066CC"
        merchantName.contains("idfc", ignoreCase = true) -> "#8B0000"
        merchantName.contains("indusind", ignoreCase = true) -> "#98272B"
        merchantName.contains("pnb", ignoreCase = true) -> "#0E2B5C"
        merchantName.contains("prime commercial bank", ignoreCase = true) -> "#0054A6"
        merchantName.contains("mbank", ignoreCase = true) -> "#ED1C24"
        merchantName.contains("al rajhi", ignoreCase = true) -> "#0066CC"
        merchantName.contains("chase", ignoreCase = true) -> "#117ACA"
        merchantName.contains("nabil", ignoreCase = true) -> "#25A64C"
